styles.globalCss:
.hp-app-main,.hp-grid { background:#07121e; }
.hp-navbar,.hp-page-header { background:#0a1828; border-color:#22384f; }
.hp-card,.hp-metric,.hp-table-wrap { background:#102237; border-color:#2b4159; box-shadow:0 8px 28px rgb(0 0 0 / 20%); }
.hp-metric { border:1px solid #29415b; border-left:0; }
.hp-metric-label { color:#8da9c0; text-transform:none; }
.hp-metric-value { color:#f0faff; font-size:23px; }
.hp-table th { background:#122a42; color:#a8c1d3; }
.hp-card-header { border-color:#2b4159; }
